import numpy as np
def amdahl(P, N):
    return 1.0 / ((1 - P) + P / N)
for P in [0.5, 0.9, 0.95, 0.99]:
    s = [amdahl(P, N) for N in [2, 8, 64, 1e9]]
    print(f"P={P}: N=2:{s[0]:.2f} N=8:{s[1]:.2f} N=64:{s[2]:.2f} 上限:{s[3]:.1f}")

def pipeline_time(k, n, t):
    return (k + n - 1) * t              # パイプライン
def sequential_time(k, n, t):
    return k * n * t                    # 逐次
k, t = 3, 10                            # 3段, 1段10ms
for n in [1, 4, 100]:
    p, s = pipeline_time(k, n, t), sequential_time(k, n, t)
    print(f"n={n:3d}: パイプライン{p}ms 逐次{s}ms 速度比{s/p:.2f}")
